from collections import defaultdict

def add_edge(g, u, v):
    if u not in g:
        g[u] = [v]
    elif v not in g[u]:
        g[u].append(v)

def dfs(node, parent, g, seen, cnt_g):
    seen.add(node)
    cnt_g += 1
    for v in g[node]:
        if v != parent:
            dfs(v, node, g, seen, cnt_g)

def separate(g, v):
    if v not in g:
        return 0, 0
    seen, cnt_root = set(), 0
    dfs(v, -1, g, seen, 0)
    for n in seen:
        if seen.count(n) == 1:
            cnt_root += 1
    return cnt_root, len(seen) - cnt_root

def p_tree(g, cnt_t):
    ans = 0
    nside = g
    while nside:
        r, k = separate(nside, nside.keys()[0])  # root
        if r == k: 
            ans += 1
        if cnt_t[r] - k > 1:
            return -1
        for n in range(1, min(cnt_t[r], k + 1)): 
            tmp = defaultdict(list)
            for x in nside[n]:
                if x < r: 
                    add_edge(tmp, x, nside[x])
                if x > r: 
                    add_edge(tmp, x, nside[r - 1][r - x])
            for x in tmp:
                nside = tmp
            nside = nside[n] if n == r else nside[r - 1]
    return ans

