                if i != len(B) - 1:
                    curr_val = curr_val + (B[i+1][0] % B[i+1][1])
                else:
                    curr_val += B[i][0] % B[i][1]
        else:
            for i in range(1, len(B)-1):
                curr_val += (B[i+1][0] % B[i+1][1])
            curr_val += B[0][0] % B[0][1] + B[-1][0] % B[-1][1]
