from itertools import accumulate

def is_decinc(arr):
    """
    Determines if an array is decinc by comparing it with all possible subsequences removed.
    """
    for i in range(len(arr)):
        for j in range(i+1):
            for k in range(len(arr)):
                if i != j and j != k and j != k and j not in arr:
                    remaining = [x for x in arr if x != j]
                    if all(remaining[i] <= x <= remaining[k] for x in remaining):
                        return False
    return True

def solve(n, p):
    """
    Calculates the number of decinc subarrays for each possible subarray start position.
    """
    prefix_sum = list(accumulate(p))
    first_occurrence = {}
    decinc_count = 0

    for i, num in enumerate(p):
        if num not in first_occurrence:
            first_occurrence[num] = i
        for j in range(num-1, 0, -1):
            if j in first_occurrence:
                decinc_count += 1

    return decinc_count

