```python
import sys

MOD = 10**9 + 7

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def hamiltonian_circuit(s, n, m):
    sequence = [i for i in range(n)]

    for i in range(n):
        prefix = [i]
        for j in range(i):
            for k in range(prefix[-1], prefix[-1] + 1):
                if s[k] - 1 < prefix[-1]:
                    prefix.append(k)
            sm = 1
            for k in range(prefix[-1] + 1, n):
                if s[k] - 1 < prefix[-1]:
                    sm *= i - 1 - prefix[-1]
                    prefix.pop()
                    break
            while prefix[-1] < len(sequence):
                if sequence[prefix[-1]] not in prefix:
                    prefix.append(sequence.pop(prefix[-1]))
            break

    return tuple([i + 1 for i in sequence])

def largest_circle(s, f, n, m):
    c, cr = 0, 0

    while c + cr < n:
        hl = []
        gl = []

        for i in range(c + cr):
            # Separate cows into groups whose cumulative overall sweetness is sweet enough for a whole cow
            if sum([s[j - i + n] for i, j in frozenset(enumerate(hl))]) - 1 <= f[i]:
                hl.append(i)
            # Separate cows into groups whose cumulative overall sweetness is not sweet enough for a full cow
            elif sum([s[j - i + n] for i, j in frozenset(enumerate(gl))]) - 1 >= f[i]:
                gl.append(i)

        # If the weight of any group passing through is smaller than f, then it means the cow contributed to sum of sweetness must be added or subtracted to one world
        while hl and sum([s[j - hl[-1] + n] for j in hl]) < f[hl[-1]]:
            hl.pop()
        while gl and sum([s[j + gl[-1] - n] for j in gl]) > f[gl[-1]]:
            gl.pop()

        # If it gets taller than available middle position, then a circle has to be cut off from operation
        if sum([max(0, s[i - hl[-1] + n + cr] - f[i] + f[hl[-1]-1]) for i in range(n)]) > (n - 1 // 2):
            cr += 1
        cur_circle_weight = c + sum([s[i - hl[-1] + n + cr] - f[i] + f[hl[-1]+1] - 1 for i in range(n)])
        if cur_circle_weight >= f[(n - 1) // 2] + cr:
            c += cr
            cr = 0

    return c + cr

def solve():
    n, m = map(int, input().split())
    s = tuple(map(int, input().split()))
    f = sorted(map(int, input().split()))
