def is_decinc(nums):
    # Accumulate negative values to mark the first decreasing subsequence starting at the left
    negative_sum = 0
    min_value = min(nums)
    max_value = max(nums) - 1
    for num in nums:
        if num > max_value:
            negative_sum += min_value
            max_value = num
        elif num < min_value:
            min_value = num
        else:
            continue
    return negative_sum <= len(nums) - 1

def count_decinc_subarrays(nums):
    prefix_sum = [0] * (n + 1)
    # Calculate prefix sums and use binary search to check for Decinc subarrays
    for i, num in enumerate(nums):
        left = bisect_left(prefix_sum, -num)
        if left == 0:
            prefix_sum[left] = -num
        else:
            prefix_sum[left] += -num
        right = bisect_right(prefix_sum, min_value - num)
        if right > 0:
            if prefix_sum[right - 1] < 0:
                decinc_count += 1
    return decinc_count

