from itertools import accumulate, groupby

def counting_increasing_subsequence(n, permutations):
    count = [1] * n
    for lengths in accumulate(permutations, initial=1):
        grouped = [key + 1 for key, group in groupby(lengths) if key == len(group)]
        for length in grouped:
            count[length-1] += len(group) * len([l for s, i in enumerate(grouped) if i>=length])
