import sys
from collections import defaultdict

def find_race_intersection(roads):
    intersections, graph = set(range(1, len(roads)+1)), defaultdict(set)
    queue = []

    for start, end in roads:
        intersections.add(start)
        inter = end
        while inter:
            if inter == start:
                continue
            if inter not in graph[start]:
                graph[start].add(inter)
                if start in queue:
                    break
                queue.append(start)
                break
            else:
                inter = inter - 1

    if len(queue) == 0:
        return -1

    index = 0
    while queue[index] < len(intersections):
        index += 1

    return index

