from typing import List

def are_decreasing_subsequence(arr: List[int]) -> bool:
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            return True
    return False

def find_decinc_pairs(n: int, p: List[int]) -> int:
    count = {'increasing': 0, 'decreasing': 0}
    current_type = 'increasing'

    for i, element in enumerate(p):
        if current_type == 'increasing':
            if i == 0 or element >= p[i-1]:
                count['increasing'] += 1
            else:
                count['decreasing'] += 1
                current_type = 'decreasing'
        else:
            if i == 0 or element <= p[i-1]:
                count['decreasing'] += 1
                current_type = 'increasing'
            else:
                count['decreasing'] += 1
                current_type = 'increasing'

    # The total number of pairs (l, r) is the power of 2 times the total number of increasing subarrays
    return (2 ** count['increasing']) * count['increasing']

