def bfs_search(tree_height):
    h = 1  # Starting height
    while (2**h - 1) < (tree_height + 1):
        h += 1  # Move to the next level
    root_addresses = [2**h + (2**i) for i in range(h)]  # Addresses of all the root nodes
    h -= 1  # Adjust to the current height
    n = h + 1  # Number of levels to explore
    while n > 1:
        size = 2**(n - 1)  # Size of each level
        x = 1  # Starting address of the next level
        addresses = [x]
        while size > 0:
            y = x + size - 1  # Address of the current node
            size //= 2  # Decrease size by half
            if (2**n + y + 1) in root_addresses:
                addresses.append(2**n + y + 1)
            for i in addresses:
                if min(i, y) % 2:
                    if (2**n + i + 1) in root_addresses:
                        addresses.append(2**n + i + 1)
            x += size * 2  # Move to the next level
        addresses = addresses[2**(n-2):]
        h -= 1
        size = 2**n
        root_addresses = sorted({y for i in addresses for y in [i-x+(2**h+x) for x in root_addresses]})
    tree_addresses = [x for x in root_addresses for y in addresses for i in [x, y] if i in root_addresses]
    target = 2**h  # Start searching from the middle of the tree
    visited = set()
    while True:
        if (target - 1) in tree_addresses:
            break
        for i in (2**h-1, 2**h+1):
            if i in tree_addresses:
                target = i
                break
        for left, right in next((prev, i) for prev in (1, (2**n-1)) for i in (prev, left+1, right-1, right)):
            if min(3 * n) <= left <= right < (3 * n):
                if left // 4 and (right-4) % 3:
                    visited.add(i)
                    break
            visited.add(i / 2)
    return tree_addresses[target-1]

