from collections import defaultdict
from itertools import combinations
from functools import lru_cache

def is_isomorphic(T1, T2):
    def dfs(u, seen):
        for v in T1[u]:
            if v in seen:
                continue
            seen.add(v)
            if u == T1[v]:
                return False
        return all(dfs(v, seen) for v in T1[u])

    t1, t2 = defaultdict(set), defaultdict(set)
    for u, v in T1.edges():
        t1[u].add(v)
        t2[v].add(u)
    return dfs(next(iter(T1)), set())

def count_non_isomorphic_trees(N):
    c, seen = 0, set()
    for edges in combinations(range(1, N+1), 2):
        seen.add(edges)
        T1 = defaultdict(set)
        for i, edge in enumerate(edges):
            T1[i+1].add(edge)
            T1[edge].add(i+1)
        for T2 in powerset(T1):
            if len(set().union(*(T2[c] for c in edges))) <= 4:
                if is_isomorphic(T1, T2):
                    c += 1

def powerset(g):
    x, *y = itertools.tee(g)
    total = next(x)
    return (* c or *powerset(i) if len(i) > 1 else ()
            for i in y
            for c in combinations((total,), len(i)))

