from collections import defaultdict, deque
from functools import cache

def find_first_obstacle(n, m, roads):
    # Build adjacency list
    roads_map = defaultdict(list)
    for u, v in roads:
        roads_map[u].append(v)

    # Extract the road with the most outgoing edges
    max_outgoing_roads = 0
    max_outgoing_edge = None
    for u, edges in roads_map.items():
        if len(edges) > max_outgoing_roads:
            max_outgoing_roads = len(edges)
            max_outgoing_edge = u

    # If the graph is connected, we can stay at the source or sink to avoid loops
    if n-1 == len(list(roads_map.keys())) - 1:
        return 1

    # Open the door on the edge with the most outgoing roads
    max_outgoing_roads, max_outgoing_edge = max_outgoing_roads, max_outgoing_roads and max_outgoing_roads[0]

    # Reverse the paths in the map and start BFS
    visited = [False]*(n+1)
    for u, edges in roads_map.items():
        visited[u+1] = True

    queue = deque([(max_outgoing_edge, 0)])
    father = {max_outgoing_edge+1: max_outgoing_edge}

    while queue:
        node, distance = queue.popleft()
        visited[node] = True

        if node == 1:
            return max_outgoing_edge

        if node+1 not in visited:
            edges = roads_map.get(father[node], [])
            for edge in edges:
                if edge < node+1:
                    queue.append((edge, distance+1))
            father[node] = max_outgoing_edge

    return -1
